def _time(t, p):
    return -np.expm1(-t[:,None]*np.exp(p))

def _lstsq(a, b):
    return np.linalg.lstsq(a, b, rcond=1e-10)[0]


def _project_operator(u, v, z, basis, start, bounds):
    def residual(rate):
        a = basis(u, rate)
